  ["mcp",`git diff ${base}..HEAD -- packages/server/src/auth/credentials.ts packages/server/src/mcp-proxy/client.ts packages/server/src/mcp-proxy/credential-resolver.ts packages/server/src/mcp-proxy/__tests__/probe-discovery.test.ts`],
  ["claims",`git diff ${base}..HEAD -- packages/server/src/tools/save_content.ts packages/server/src/__tests__/integration/events/save-content-member-claim-heal.test.ts packages/server/src/auth/install-operator.ts`],
  ["errors",`git diff ${base}..HEAD -- packages/core/src/errors.ts packages/server/src/rest-api.ts packages/server/src/tools packages/server/src/watchers/automation.ts packages/server/src/worker-api/behavior-trigger.ts packages/server/src/utils/organization-access.ts packages/server/src/utils/execution-context.ts packages/server/src/__tests__/unit/rest-error-status.test.ts`],
  ["reaction_sentry",`git diff ${base}..HEAD -- packages/server/src/tools/admin/manage_behaviors/complete-window.ts packages/server/src/__tests__/unit/watchers/reaction-retry-classification.test.ts packages/server/src/instrument.ts packages/server/src/scheduled/task-scheduler.ts packages/agent-worker/src/core/error-handler.ts packages/agent-worker/src/runtime/session-context.ts packages/agent-worker/src/runtime/session-runner.ts packages/server/src/utils/__tests__/render-agent-error.test.ts`],
  ["diffcheck",`git diff --check ${base}..HEAD; git diff --stat ${base}..HEAD; git diff --name-status ${base}..HEAD`]
];
const results = await Promise.all(cmds.map(async ([name,cmd]) => {
  const out = await tools.exec_command({cmd,workdir:"/Users/burakemre/Code/lobu/.claude/worktrees/review-pr2744",yield_time_ms:30000,max_output_tokens:40000});
