const baseSha = "$(git merge-base origin/main HEAD)";
const cmds = [
  ["overlap",`comm -12 <(git diff --name-only ${baseSha}..origin/main | sort) <(git diff --name-only ${baseSha}..HEAD | sort)`],
  ["zai","rg -n -i \"z-ai|z\\.ai|Z_AI|ZAI\" --glob '!bun.lock' --glob '!packages/owletto/**' . | head -n 240"],
  ["provider_count","jq 'if type==\"array\" then length else (.providers // .catalog // []) | length end' config/providers.json; jq -r 'if type==\"array\" then .[] else (.providers // .catalog // [])[] end | [.id,.name] | @tsv' config/providers.json | nl -ba; rg -n \"claude-sonnet-5|sonnet-4-5|claude-sonnet-4-5\" config/providers.json packages/agent-worker examples | head -n 160"],
  ["feedback","sed -n '1,540p' packages/server/src/tools/admin/manage_behaviors/feedback.ts; sed -n '1,150p' packages/server/src/tools/admin/manage_behaviors/trigger.ts; rg -n \"behavior_id.*safe|parse.*behavior|positive.*integer|safeInteger|Number\\.isSafeInteger|parseBehavior\" packages/server/src packages/core/src | head -n 240"],
  ["instrument","sed -n '1,180p' packages/server/src/instrument.ts; sed -n '1,130p' packages/server/src/utils/runtime-info.ts; rg -n \"instrument|sentryEnvironment|resolveRuntimeEnvironment\" packages/server/src/__tests__ packages/server/src --glob '*test.ts' | head -n 160"],
  ["mcpclient","sed -n '1,520p' packages/server/src/mcp-proxy/client.ts; sed -n '1,300p' packages/server/src/auth/credentials.ts; sed -n '300,620p' packages/server/src/auth/credentials.ts"],
  ["saveclaim","sed -n '1,280p' packages/server/src/tools/save_content.ts; sed -n '1,260p' packages/server/src/__tests__/integration/events/save-content-member-claim-heal.test.ts; sed -n '1,240p' packages/server/src/auth/install-operator.ts"]
];
const results = await Promise.all(cmds.map(async ([name,cmd]) => {
  const out = await tools.exec_command({cmd,workdir:"/Users/burakemre/Code/lobu/.claude/worktrees/review-pr2744",yield_time_ms:30000,max_output_tokens:40000,shell:"zsh"});
  return {name,...out};
}));
for (const x of results) text(`--- ${x.name} (exit ${x.exit_code}) ---\n${x.output}`);

