/**
 * MCP Proxy Client
 *
 * Manages sessions and JSON-RPC communication with upstream MCP servers.
 * Sessions are stored in-memory (per-connection, not serializable).
 * Tool discovery cache is stored in-process with a short TTL.
 */

import { MCP_PROTOCOL_VERSION } from '@lobu/core';
import { isReservedIp, stripIpv6Brackets } from '../gateway/proxy/ssrf-guard';
import { errorMessage } from '../utils/errors';
import logger from '../utils/logger';
import { TtlCache } from '../utils/ttl-cache';
import {
  type ResolvedCredentials,
  resolveCredentialsByConnectionId,
} from './credential-resolver';
import { parseJsonRpcResponse } from './http-response';
import type {
  DiscoveredTool,
  JsonRpcResponse,
  McpOAuthClientRegistration,
  McpOAuthMetadata,
  McpProxyConfig,
} from './types';

const FETCH_TIMEOUT_INIT_MS = 10_000;
const FETCH_TIMEOUT_TOOL_MS = 30_000;
const TOOL_CACHE_TTL_MS = 5 * 60 * 1000;
const SESSION_TTL_MS = 30 * 60 * 1000;

function fetchWithTimeout(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  return fetch(url, { ...init, signal: controller.signal }).finally(() => clearTimeout(timer));
}

/**
 * In-memory session store. Sessions include connectionId whenever the caller
 * targets a specific connection so two accounts on the same connector never
 * reuse each other's authenticated MCP session; only connection-less
 * (unauthenticated) discovery uses the connector-wide key.
 */
type McpSessionState = { sessionId: string; protocolVersion: string };
const sessions = new TtlCache<McpSessionState>(SESSION_TTL_MS);

/**
 * The upstream rejected the request because it does not recognize our session
 * id (MCP Streamable HTTP: an unknown/expired session MUST get a 404). The
 * upstream never reached the tool, so replaying after a fresh handshake cannot
 * double-execute an action — unlike a timeout or a 5xx, which stay fatal.
 */
class McpSessionExpiredError extends Error {}

class McpOAuthRequiredError extends Error {
  constructor(readonly metadata: McpOAuthMetadata) {
    super('MCP server requires OAuth authorization');
    this.name = 'McpOAuthRequiredError';
  }
}

/**
 * The upstream rejected the credentials we sent (HTTP 401). Unlike a session
 * rejection this MAY be a dead/revoked access token whose stored expiry still
 * looks valid, so the caller re-resolves against the exact rejected token and
 * retries once.
 */
class McpAuthRejectedError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'McpAuthRejectedError';
  }
}

async function refreshRejectedCredentials(
  connectionId: number,
  orgId: string,
  credentials: ResolvedCredentials | null
): Promise<ResolvedCredentials | null> {
  if (!credentials?.accessToken) return null;
  try {
    return await resolveCredentialsByConnectionId(connectionId, orgId, {
      rejectedAccessToken: credentials.accessToken,
    });
  } catch {
    return null;
  }
}

function sessionKey(orgId: string, connectorKey: string, connectionId?: number): string {
  return connectionId === undefined
    ? `${orgId}:${connectorKey}`
    : `${orgId}:${connectorKey}:connection:${connectionId}`;
}

// ---------------------------------------------------------------------------
const toolCache = new TtlCache<DiscoveredTool[]>(TOOL_CACHE_TTL_MS);

// ---------------------------------------------------------------------------
// Upstream communication
// ---------------------------------------------------------------------------

/**
 * Build headers for an upstream MCP request.
 */
function buildHeaders(
  credentials: ResolvedCredentials | null,
  session: McpSessionState | null
): Record<string, string> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    Accept: 'application/json, text/event-stream',
  };

  if (session) {
    headers['Mcp-Session-Id'] = session.sessionId;
    headers['MCP-Protocol-Version'] = session.protocolVersion;
  }

  if (credentials?.accessToken) {
    headers.Authorization = `${credentials.tokenType || 'Bearer'} ${credentials.accessToken}`;
  }

  return headers;
}

/**
 * Send a JSON-RPC request to an upstream MCP server.
 * Tracks Mcp-Session-Id from responses.
 */
async function sendRequest(
  upstreamUrl: string,
  credentials: ResolvedCredentials | null,
  orgId: string,
  connectorKey: string,
  body: string,
  timeoutMs: number = FETCH_TIMEOUT_TOOL_MS,
  connectionId?: number
): Promise<JsonRpcResponse> {
  // Re-validate on every outbound fetch — config may have been edited/imported
  // after the creation-time probe, so "validated at write time" is not enough.
  assertSafeUrl(upstreamUrl);
  const key = sessionKey(orgId, connectorKey, connectionId);
  const session = sessions.get(key) ?? null;
  const headers = buildHeaders(credentials, session);

  const response = await fetchWithTimeout(
    upstreamUrl,
    { method: 'POST', headers, body },
    timeoutMs
  );

  // Track session ID from response
  const newSessionId = response.headers.get('Mcp-Session-Id');
  if (newSessionId) {
    sessions.set(key, {
      sessionId: newSessionId,
      protocolVersion: session?.protocolVersion ?? MCP_PROTOCOL_VERSION,
    });
  }

  if (!response.ok) {
    const text = await response.text();
    if (response.status === 404 && session) {
      sessions.delete(key);
      throw new McpSessionExpiredError(`Upstream MCP returned 404: ${text}`);
    }
    if (response.status === 401) {
      throw new McpAuthRejectedError(`Upstream MCP returned 401: ${text}`);
    }
    throw new Error(`Upstream MCP returned ${response.status}: ${text}`);
  }

  const request = JSON.parse(body) as { id?: unknown };
  const expectedId = Object.hasOwn(request, 'id') ? request.id : undefined;
  return (await parseJsonRpcResponse(response, expectedId)) as JsonRpcResponse;
}

/**
 * Initialize an MCP session with the upstream server.
 * Sends initialize + notifications/initialized handshake.
 */
async function initializeSession(
  upstreamUrl: string,
  credentials: ResolvedCredentials | null,
  orgId: string,
  connectorKey: string,
  connectionId?: number
): Promise<Record<string, unknown>> {
  // Clear existing session
  const key = sessionKey(orgId, connectorKey, connectionId);
  sessions.delete(key);

  // Send initialize
  const initResponse = await sendRequest(
    upstreamUrl,
    credentials,
    orgId,
    connectorKey,
    JSON.stringify({
      jsonrpc: '2.0',
      method: 'initialize',
      params: {
        protocolVersion: MCP_PROTOCOL_VERSION,
        capabilities: {},
        clientInfo: { name: 'lobu-mcp-proxy', version: '1.0.0' },
      },
      id: 0,
    }),
    FETCH_TIMEOUT_INIT_MS,
    connectionId
  );

  if (initResponse.error) {
    throw new Error(`MCP initialize failed: ${initResponse.error.message}`);
  }

  const protocolVersion = initResponse.result?.protocolVersion;
  if (typeof protocolVersion !== 'string' || protocolVersion.length === 0) {
    throw new Error('MCP initialize response omitted protocolVersion');
  }
  const initializedSession = sessions.get(key);
  if (initializedSession) {
    sessions.set(key, { ...initializedSession, protocolVersion });
  }

  // Send initialized notification
  try {
    await sendRequest(
      upstreamUrl,
      credentials,
      orgId,
      connectorKey,
      JSON.stringify({
        jsonrpc: '2.0',
        method: 'notifications/initialized',
      }),
      FETCH_TIMEOUT_INIT_MS,
      connectionId
    );
  } catch {
    // Notification delivery is best-effort
  }

  return initResponse.result?.capabilities ?? {};
}

/**
 * Discover tools from an upstream MCP server.
 * Returns tools with the tool_prefix applied to names.
 */
export async function discoverTools(
  connectorKey: string,
  config: McpProxyConfig,
  orgId: string,
  connectionId?: number
): Promise<DiscoveredTool[]> {
  // Key the cache by org AND connection — two orgs can each define a connector
  // with the same key but different upstream URLs / tool sets, and two
  // connections in one org can hold different accounts whose upstream exposes
  // different tools; sharing either cache leaks one catalog to the other.
  const cacheKey = sessionKey(orgId, connectorKey, connectionId);
  const cached = toolCache.get(cacheKey) ?? null;
  if (cached) return cached;

  let credentials =
    connectionId === undefined
      ? null
      : await resolveCredentialsByConnectionId(connectionId, orgId);

  let canRefreshAfter401 = connectionId !== undefined;
  while (true) {
    try {
      // Initialize session first
      const capabilities = await initializeSession(
        config.upstream_url,
        credentials,
        orgId,
        connectorKey,
        connectionId
      );

      // A server that does not advertise tools is legitimately toolless. Once it
      // advertises the capability, however, tools/list is part of the negotiated
      // contract and discovery failures must fail the install instead of silently
      // persisting a connector with zero operations.
      if (!Object.hasOwn(capabilities, 'tools')) {
        toolCache.set(cacheKey, []);
        return [];
      }

      // Fetch tools/list
      const response = await sendRequest(
        config.upstream_url,
        credentials,
        orgId,
        connectorKey,
        JSON.stringify({
          jsonrpc: '2.0',
          method: 'tools/list',
          params: {},
          id: 1,
        }),
        FETCH_TIMEOUT_TOOL_MS,
        connectionId
      );

      if (response.error) {
        throw new Error(`MCP tools/list failed: ${response.error.message}`);
      }

      const rawTools = response.result?.tools;
      if (!Array.isArray(rawTools)) {
        throw new Error('MCP tools/list response omitted tools');
      }
      const prefix = config.tool_prefix;

      const tools: DiscoveredTool[] = rawTools.map((t) => ({
        name: `${prefix}__${t.name}`,
        originalName: t.name,
        description: t.description ?? '',
        inputSchema: t.inputSchema ?? { type: 'object', properties: {} },
        annotations: t.annotations,
        connectorKey,
        upstreamUrl: config.upstream_url,
      }));

      toolCache.set(cacheKey, tools);

      logger.info(
        { connectorKey, toolCount: tools.length, prefix },
        '[McpProxy] Discovered tools from upstream MCP'
      );

      return tools;
    } catch (error) {
      if (
        canRefreshAfter401 &&
        error instanceof McpAuthRejectedError &&
        connectionId !== undefined
      ) {
        canRefreshAfter401 = false;
        logger.info(
          { connectorKey, url: config.upstream_url, connectionId },
          '[McpProxy] Tool discovery rejected (401); refreshing and retrying once'
        );
        const refreshed = await refreshRejectedCredentials(
          connectionId,
          orgId,
          credentials
        );
        if (refreshed?.accessToken) {
          credentials = refreshed;
          sessions.delete(cacheKey);
          toolCache.delete(cacheKey);
          continue;
        }
      }

      logger.error(
        { connectorKey, url: config.upstream_url, error: errorMessage(error) },
        '[McpProxy] Tool discovery failed'
      );
      throw error;
    }
  }
}

/**
 * Call a tool on an upstream MCP server.
 * Handles stale session recovery: reinitialize + retry once.
 */
export async function callTool(
  connectorKey: string,
  config: McpProxyConfig,
  orgId: string,
  originalToolName: string,
  args: Record<string, unknown>,
  connectionId: number
): Promise<{ content: unknown[]; isError: boolean }> {
  let credentials = await resolveCredentialsByConnectionId(connectionId, orgId);
  let canRefreshAfter401 = true;

  const key = sessionKey(orgId, connectorKey, connectionId);

  // Establish a session before the action call. A transport failure after a
  // tools/call is ambiguous — the upstream may have executed the action before
  // the response was lost — so it must never be interpreted as permission to
  // initialize and replay a potentially destructive call.
  if (!sessions.get(key)) {
    try {
      await initializeSession(
        config.upstream_url,
        credentials,
        orgId,
        connectorKey,
        connectionId
      );
    } catch (error) {
      if (!(error instanceof McpAuthRejectedError)) throw error;
      const refreshed = await refreshRejectedCredentials(connectionId, orgId, credentials);
      if (!refreshed?.accessToken) throw error;
      canRefreshAfter401 = false;
      credentials = refreshed;
      await initializeSession(
        config.upstream_url,
        credentials,
        orgId,
        connectorKey,
        connectionId
      );
    }
  }

  const jsonRpcBody = JSON.stringify({
    jsonrpc: '2.0',
    method: 'tools/call',
    params: { name: originalToolName, arguments: args },
    id: 1,
  });

  const send = (): Promise<JsonRpcResponse> =>
    sendRequest(
      config.upstream_url,
      credentials,
      orgId,
      connectorKey,
      jsonRpcBody,
      FETCH_TIMEOUT_TOOL_MS,
      connectionId
    );

  // One bounded recovery loop for every safe-to-retry outcome. The ONLY
  // retried cases are explicit no-execution signals: a 401 auth rejection
  // (first attempt never produced a response), a 404 session rejection, or a
  // JSON-RPC "not initialized" error. A timeout/5xx is ambiguous (the upstream
  // may have executed the action) and must surface, never replay. Each
  // recovery can rotate the token at most once (canRefreshAfter401) and
  // rehandshake at most once per class, so the loop cannot spin. Every
  // initializeSession call runs INSIDE the try so a 401 from a recovery
  // reinitialize routes back through the refresh path instead of escaping.
  let response: JsonRpcResponse;
  let phase: 'send' | 'reinitialize' = 'send';
  let sessionRecovered = false;
  while (true) {
    try {
      if (phase === 'reinitialize') {
        await initializeSession(
          config.upstream_url,
          credentials,
          orgId,
          connectorKey,
          connectionId
        );
      }
      response = await send();
    } catch (error) {
      // Refresh-on-401: the upstream rejected the access token even though its
      // stored expiry looked valid (tokens get revoked upstream). Re-resolve
      // against the exact rejected token under the per-account lock, drop the
      // stale session, reinitialize, and retry once. A still-failing 401 means
      // the refresh token itself is dead — surface it rather than loop.
      if (canRefreshAfter401 && error instanceof McpAuthRejectedError) {
        canRefreshAfter401 = false;
        logger.info(
          { connectorKey, originalToolName, connectionId },
          '[McpProxy] Upstream rejected access token; refreshing and retrying once'
        );
        const refreshed = await refreshRejectedCredentials(connectionId, orgId, credentials);
        if (!refreshed?.accessToken) throw error;
        credentials = refreshed;
        sessions.delete(sessionKey(orgId, connectorKey, connectionId));
        phase = 'reinitialize';
        continue;
      }
      // A rejected session id means the call never ran upstream; rehandshake
      // and replay. This reinitialize may itself 401 (both an expired session
      // AND a revoked token) — the loop routes that through the refresh above.
      if (!sessionRecovered && error instanceof McpSessionExpiredError) {
        sessionRecovered = true;
        logger.info(
          { connectorKey, originalToolName },
          '[McpProxy] Session rejected, reinitializing'
        );
        phase = 'reinitialize';
        continue;
      }
      // Ambiguous transport failure — the upstream may have executed the action.
      throw error;
    }

    // Stale-session response recovery ("not initialized"): the call never ran,
    // so rehandshake and replay — same uniform path as the thrown 404 above.
    if (response.error && /not initialized/i.test(response.error.message || '')) {
      if (!sessionRecovered) {
        sessionRecovered = true;
        logger.info(
          { connectorKey, originalToolName },
          '[McpProxy] Session expired, reinitializing'
        );
        phase = 'reinitialize';
        continue;
      }
    }
    break;
  }

  if (response.error) {
    return {
      content: [{ type: 'text', text: response.error.message || 'Upstream MCP error' }],
      isError: true,
    };
  }

  return {
    content: response.result?.content ?? [],
    isError: response.result?.isError ?? false,
  };
}

/**
 * Credential Service — OAuth token resolution and refresh
 *
 * Used by execution-context.ts and mcp-proxy/credential-resolver.ts to
 * resolve and auto-refresh OAuth tokens for upstream API calls.
 */

import type { DbClient } from '../db/client';
import { buildRefreshRequest, parseTokenRefreshResponse } from './oauth/token-refresh';

/**
 * Credential tokens for sync execution
 */
interface CredentialTokens {
  provider: string;
  accessToken: string | null;
  refreshToken: string | null;
  expiresAt: Date | null;
  scope: string | null;
}

const TOKEN_EXPIRY_BUFFER_MS = 5 * 60 * 1000;

function isTokenExpiringSoon(expiresAt: Date | string | null): boolean {
  if (!expiresAt) return false;
  return new Date(expiresAt).getTime() <= Date.now() + TOKEN_EXPIRY_BUFFER_MS;
}

/**
 * Per-account advisory-lock tag. `pg_advisory_xact_lock(hashtext($1))` keys the
 * lock off this string and auto-releases at transaction end, serializing OAuth
 * token refresh across replicas so two workers can't both rotate the same
 * account's refresh token and clobber each other's result.
 */
function refreshLockTag(accountId: string): string {
  return `oauth_account_refresh:${accountId}`;
}

export class CredentialService {
  constructor(private sql: DbClient) {}

  /**
   * Get OAuth tokens for a connection (V1 integration platform).
   * Reads from auth_profiles.account_id -> account table.
   * Optionally accepts oauthConfig for generic token refresh (non-Google providers).
   */
  async getConnectionTokens(
    _connectionId: number,
    accountId: string,
    oauthConfig?: {
      tokenUrl: string;
      clientId: string;
      clientSecret?: string;
      authMethod?: 'client_secret_post' | 'client_secret_basic' | 'none';
      resource?: string;
    },
    opts?: { rejectedAccessToken?: string }
  ): Promise<CredentialTokens | null> {
    const result = await this.sql`
      SELECT
        a."providerId" as provider,
        a."accessToken" as "accessToken",
        a."refreshToken" as "refreshToken",
        a."accessTokenExpiresAt" as "expiresAt",
        a.scope
      FROM "account" a
      WHERE a.id = ${accountId}
    `;

    if (result.length === 0) return null;

    const tokens = result[0] as unknown as CredentialTokens;

    // Refresh a token rejected upstream even when its stored expiry looks
    // valid. Carry the exact rejected token through the lock: if another
    // replica already replaced it, its fresh value wins and must not be
    // rotated again by every waiter that observed the same 401.
    const rejectedAccessToken = opts?.rejectedAccessToken;
    const currentTokenWasRejected =
      rejectedAccessToken !== undefined && tokens.accessToken === rejectedAccessToken;
    if (
      tokens.refreshToken &&
      oauthConfig &&
      (currentTokenWasRejected || isTokenExpiringSoon(tokens.expiresAt))
    ) {
      const newTokens = await this.refreshAccountUnderLock(accountId, oauthConfig, {
        rejectedAccessToken: currentTokenWasRejected ? rejectedAccessToken : undefined,
      });
      if (newTokens) {
        return {
          ...tokens,
          accessToken: newTokens.accessToken,
          expiresAt: newTokens.expiresAt,
        };
      }
      if (currentTokenWasRejected) return null;
    }

    return tokens;
  }

  /**
   * Public method for refreshing tokens with explicit OAuth config.
   * Used by the MCP proxy to refresh tokens using connector-specific OAuth settings.
   *
   * Serialized per account under a Postgres advisory lock with the stored
   * refresh token re-read inside the lock — so concurrent refreshes across
   * replicas can't both rotate and clobber each other's persisted token.
   */
  async refreshWithConfig(config: {
    tokenUrl: string;
    clientId: string;
    clientSecret?: string;
    refreshToken: string;
    authMethod?: 'client_secret_post' | 'client_secret_basic' | 'none';
    resource?: string;
    accountId: string;
  }): Promise<{ accessToken: string; expiresAt: Date; refreshToken?: string } | null> {
    return this.refreshAccountUnderLock(config.accountId, {
      tokenUrl: config.tokenUrl,
      clientId: config.clientId,
      clientSecret: config.clientSecret,
      authMethod: config.authMethod,
      resource: config.resource,
    });
  }

  /**
   * Refresh + persist an account's OAuth token under a per-account Postgres
   * advisory lock. The lock is held for the whole transaction; the stored
   * refresh token and expiry are RE-READ inside the lock so that if a
   * concurrent refresh (this pod or another replica) already rotated the
   * token, the loser uses the freshly-stored refresh token / no-ops on a
   * still-valid expiry instead of replaying a rotated-away token.
   */
  private async refreshAccountUnderLock(
    accountId: string,
    oauthConfig: {
      tokenUrl: string;
      clientId: string;
      clientSecret?: string;
      authMethod?: 'client_secret_post' | 'client_secret_basic' | 'none';
      resource?: string;
    },
    opts?: { rejectedAccessToken?: string }
  ): Promise<{ accessToken: string; expiresAt: Date; refreshToken?: string } | null> {
    return this.sql.begin(async (tx) => {
      await tx.unsafe(`SELECT pg_advisory_xact_lock(hashtext($1))`, [
        refreshLockTag(accountId),
      ]);

      // Re-read under the lock: a concurrent refresh may have rotated the
      // refresh token and pushed the expiry out while we waited to acquire it.
      const rows = await tx`
        SELECT
          a."accessToken" as "accessToken",
          a."refreshToken" as "refreshToken",
          a."accessTokenExpiresAt" as "expiresAt"
        FROM "account" a
        WHERE a.id = ${accountId}
        FOR UPDATE
      `;
      const current = rows[0] as
        | { accessToken: string | null; refreshToken: string | null; expiresAt: Date | null }
        | undefined;
      if (!current?.refreshToken) return null;

      // A waiter refreshing after a 401 must compare the token it actually sent
      // with the row re-read under the lock. If they differ, another replica
      // already recovered the account; return that token instead of rotating
      // the new refresh token a second time.
      if (
        opts?.rejectedAccessToken !== undefined &&
        current.accessToken !== opts.rejectedAccessToken &&
        current.accessToken &&
        current.expiresAt
      ) {
        return {
          accessToken: current.accessToken,
          expiresAt: new Date(current.expiresAt),
        };
      }

      if (
        opts?.rejectedAccessToken === undefined &&
        current.expiresAt &&
        !isTokenExpiringSoon(current.expiresAt)
      ) {
        return current.accessToken
          ? { accessToken: current.accessToken, expiresAt: new Date(current.expiresAt) }
          : null;
      }

      const result = await this.refreshTokenGeneric({
        ...oauthConfig,
        refreshToken: current.refreshToken,
      });
      if (!result) return null;

      await this.persistAccountTokens(accountId, result, tx);
      return result;
    });
  }

  private async persistAccountTokens(
    accountId: string,
    tokens: { accessToken: string; expiresAt: Date; refreshToken?: string },
    sql: DbClient = this.sql
  ): Promise<void> {
    await sql`
      UPDATE "account"
      SET "accessToken" = ${tokens.accessToken},
          "accessTokenExpiresAt" = ${tokens.expiresAt.toISOString()},
          "refreshToken" = COALESCE(${tokens.refreshToken ?? null}, "refreshToken"),
          "updatedAt" = NOW()
      WHERE id = ${accountId}
    `;
  }

  /**
   * Generic OAuth token refresh supporting multiple auth methods.
   * Ported from Termos GenericOAuth2Client.refreshToken().
   */
  async refreshTokenGeneric(params: {
    tokenUrl: string;
    clientId: string;
    clientSecret?: string;
    refreshToken: string;
    authMethod?: 'client_secret_post' | 'client_secret_basic' | 'none';
    resource?: string;
  }): Promise<{ accessToken: string; expiresAt: Date; refreshToken?: string } | null> {
    const { headers, body } = buildRefreshRequest({
      profile: 'account-credential',
      clientId: params.clientId,
      clientSecret: params.clientSecret,
      refreshToken: params.refreshToken,
      authMethod: params.authMethod,
      resource: params.resource,
    });

    try {
      const response = await fetch(params.tokenUrl, {
        method: 'POST',
        headers,
        body,
      });

      if (!response.ok) {
        console.error('[Credentials] Generic token refresh failed:', await response.text());
        return null;
      }

      const data = (await response.json()) as Record<string, unknown>;
      const parsed = parseTokenRefreshResponse(data);
      if (!parsed) {
        console.error('[Credentials] Generic token refresh returned no access_token');
        return null;
      }

      return {
        accessToken: parsed.accessToken,
        expiresAt: new Date(parsed.expiresAtMs),
        refreshToken: parsed.refreshToken,
      };
    } catch (error) {
      console.error('[Credentials] Generic token refresh error:', error);
      return null;
    }
  }
}

