export const saveContent = withValidatedArgs('save_memory', SaveContentSchema, saveContentImpl);

async function saveContentImpl(
  args: SaveContentArgs,
  _env: Env,
  ctx: ToolContext
): Promise<SaveContentResult> {
  // SDK delegates (`client.knowledge.save`) skip `checkToolAccess`, so apply
  // the same member+scope gate here. System contexts (userId=null + auth=true)
  // bypass — watcher reactions don't carry a user identity.
  if (!isSystemContext(ctx)) {
    if (!ctx.memberRole) {
      throw new ToolUserError('save_memory requires workspace membership with write access.', 403);
    }
    if (!hasRequiredMcpScope('write', ctx.scopes)) {
      throw new ToolUserError('save_memory requires an MCP session with write access.', 403);
    }
  }

  const sql = getDb();

  // 0. Ensure $member entity type exists for this org
  await ensureMemberEntityType(ctx.organizationId);

  const entityIds: number[] = args.entity_ids ?? [];
  const semanticType = args.semantic_type;
  if (!semanticType) throw new ToolUserError('semantic_type is required');

  // `guidance` is the built-in org-wide context kind: current guidance events
  // are injected into EVERY agent's system prompt (workspace instructions +
  // worker session context), which makes authorship a prompt-injection
  // surface. Fail closed: only org owners/admins may author it — system
  // contexts (watcher reactions, memberRole=null) and plain members are
/**
 * Integration test: save_content's $member auth_user_id claim write heals its
 * pre-existing legacy wrong-source row.
 *
 * The authz channel-visibility gate resolves a user to their $member via an
 * entity_identities row with namespace `auth_user_id` AND
 * `source_connector='auth:signup'`. save_content used to write that claim with
 * `source_connector='save_content'`; because idx_entity_identities_live_unique
 * is on (org, namespace, identifier), the wrong-source row BLOCKED the correct
 * auth:signup insert forever — a permanent poison the member-claim-drift
 * detector reports but cannot repair. The fix writes `auth:signup` and heals
 * that legacy source on conflict without promoting other identity sources.
 *
 * DB-backed (save_content writes events + entity_identities), so it runs
 * against the pgvector DB via DATABASE_URL.
 */

import { beforeAll, beforeEach, describe, expect, it } from 'vitest';
import type { ToolContext } from '../../../tools/registry';
import { saveContent } from '../../../tools/save_content';
import { runMemberClaimDriftCheck } from '../../../scheduled/member-claim-drift';
import { initWorkspaceProvider } from '../../../workspace';
import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
import {
  addUserToOrganization,
  createTestEntity,
  createTestOrganization,
  createTestUser,
  seedSystemEntityTypes,
} from '../../setup/test-fixtures';

describe('saveContent > $member auth_user_id claim heals poison source', () => {
  let org: Awaited<ReturnType<typeof createTestOrganization>>;
  let user: Awaited<ReturnType<typeof createTestUser>>;
  let memberId: number;

  beforeAll(async () => {
    await initWorkspaceProvider();
  });

  beforeEach(async () => {
    await cleanupTestDatabase();
    await seedSystemEntityTypes();
    org = await createTestOrganization({ name: 'Member Claim Heal Org' });
    user = await createTestUser({ email: 'claim-heal@example.com' });
    await addUserToOrganization(user.id, org.id, 'owner');

    // The user's $member entity with an email identity, exactly as the
    // email-based resolution in save_content step 4 expects.
    const member = await createTestEntity({
      name: user.email,
      entity_type: '$member',
      organization_id: org.id,
    });
    memberId = member.id;
    const sql = getTestDb();
    await sql`
      INSERT INTO entity_identities
        (organization_id, entity_id, namespace, identifier, source_connector)
      VALUES
        (${org.id}, ${memberId}, 'email', ${user.email}, 'auth:signup')
    `;
    // The PRE-FIX poison state: save_content historically wrote this row with
    // the wrong source, which blocks the auth:signup insert on the unique
    // (org, namespace, identifier) index.
    await sql`
      INSERT INTO entity_identities
        (organization_id, entity_id, namespace, identifier, source_connector)
      VALUES
        (${org.id}, ${memberId}, 'auth_user_id', ${user.id}, 'save_content')
      ON CONFLICT (organization_id, namespace, identifier)
        WHERE deleted_at IS NULL
      DO NOTHING
    `;
  });

  function ctx(): ToolContext {
    return {
      organizationId: org.id,
      userId: user.id,
      memberRole: 'owner',
      isAuthenticated: true,
      tokenType: 'oauth',
      scopedToOrg: false,
      allowCrossOrg: true,
      scopes: ['mcp:write'],
      sourceContext: null,
    } as ToolContext;
  }

  it('heals the poison auth_user_id claim to auth:signup and appends the member', async () => {
    const result = await saveContent(
      {
        content: 'A save from the owner should repair their member claim.',
        semantic_type: 'note',
        title: 'claim heal',
        metadata: {},
      } as never,
      {} as never,
      ctx()
    );

    expect(result.entity_ids).toContain(memberId);

    const sql = getTestDb();
    const rows = await sql<{ source_connector: string; entity_id: number }>`
      SELECT source_connector, entity_id
      FROM entity_identities
      WHERE organization_id = ${org.id}
        AND namespace = 'auth_user_id'
        AND identifier = ${user.id}
        AND deleted_at IS NULL
    `;
    // The poison row is gone (single claim, healed to auth:signup, pointing at
    // the $member entity) — no duplicate with the old source survives.
    expect(rows).toHaveLength(1);
    expect(rows[0]!.source_connector).toBe('auth:signup');
    expect(rows[0]!.entity_id).toBe(memberId);

    // The drift detector sees a resolvable claim now.
    await expect(runMemberClaimDriftCheck()).resolves.toEqual({
      missingClaim: 0,
      poisonClaim: 0,
    });
  });

  it('does not promote a claim written by an untrusted source', async () => {
    const sql = getTestDb();
    await sql`
      UPDATE entity_identities
      SET source_connector = 'user:provided'
      WHERE organization_id = ${org.id}
        AND namespace = 'auth_user_id'
        AND identifier = ${user.id}
        AND deleted_at IS NULL
    `;

    await saveContent(
      {
        content: 'An untrusted identity claim must stay untrusted.',
        semantic_type: 'note',
        title: 'claim trust boundary',
        metadata: {},
      } as never,
      {} as never,
      ctx()
    );

    const rows = await sql<{ source_connector: string }>`
      SELECT source_connector
      FROM entity_identities
      WHERE organization_id = ${org.id}
        AND namespace = 'auth_user_id'
        AND identifier = ${user.id}
        AND deleted_at IS NULL
    `;
    expect(rows).toEqual([{ source_connector: 'user:provided' }]);
  });
});
/**
 * Install-operator bootstrap.
 *
 * At first `lobu run` boot, this provisions a synthetic `install_operator`
 * user so headless installs (CI, containers, /tmp scaffolds without a
 * browser) can sign in via better-auth without a chicken-and-egg /sign-up
 * step. The operator's password is the install's `ENCRYPTION_KEY` —
 * already in `.env` for at-rest encryption, now doing double duty as the
 * install secret. See `docs/plans/install-operator-bootstrap.md` for the full
 * design.
 *
 * Idempotent. Safe to call on every boot.
 */

import { hostname } from 'node:os';
import { hashPassword } from 'better-auth/crypto';
import { assertEncryptionKey } from '@lobu/core';
import { getDb } from '../db/client';
import { generateSecureToken } from './oauth/utils';
import { ensurePersonalOrganization } from './personal-org-provisioning';

export const INSTALL_OPERATOR_KIND = 'install_operator' as const;

/**
 * Deterministic synthetic email for the install operator. Not a real
 * deliverable address — no password reset / magic link will ever reach
 * it (and the carve-outs in `auth/index.tsx` reject those flows
 * anyway). Using `<hostname>` keeps it stable across reboots on the
 * same host; falls back to `localhost` when `hostname()` is empty.
 */
function installOperatorEmail(): string {
  return `install@${hostname() || 'localhost'}`.toLowerCase();
}

/**
 * Provision the install operator user + credential account + personal
 * org if they don't yet exist. Idempotent.
 *
 * Returns the operator user id (whether it existed or was just created)
 * so callers can chain further setup against the operator's personal org
 * if they want to.
 */
export async function ensureInstallOperator(): Promise<{
  userId: string;
  created: boolean;
}> {
  const encryptionKey = process.env.ENCRYPTION_KEY;
  if (!encryptionKey) {
    throw new Error(
      'ensureInstallOperator: ENCRYPTION_KEY is required. Set it in .env or opt into ephemeral keys with LOBU_ALLOW_EPHEMERAL_ENCRYPTION_KEY=1 (which gateway.ts will generate before this is called).'
    );
  }
  // Validate shape NOW, not later. `hashPassword` happily accepts any
  // string, so a malformed key would bootstrap the operator fine — but
  // then every encrypt/decrypt call (saving a provider API key, etc.)
  // would 500 with the same canonical message. Fail at install instead
  // of leaving a half-broken operator that can sign in but can't
  // persist any encrypted secret.
  assertEncryptionKey(encryptionKey);

  const sql = getDb();

  // Convergent provisioning: every boot ensures each step exists. The
  // user/account rows are immutable (we never re-hash on top of an
  // existing password — that would silently rotate credentials when
  // ENCRYPTION_KEY changed). But the personal-org step lives outside
  // the user-creation txn, so a transient failure there used to leave
  // the operator permanently broken: subsequent boots would see the
  // user row and skip provisioning entirely, and `/api/local-init`
  // would loop forever on `personal_org_missing`. Now we check each
  // step independently and patch missing pieces.
  const existing = (await sql`
    SELECT id, email FROM "user"
     WHERE principal_kind = ${INSTALL_OPERATOR_KIND}
     LIMIT 1
  `) as unknown as Array<{ id: string; email: string }>;

  let userId: string;
  let userEmail: string;
  let created: boolean;

  if (existing.length > 0) {
    userId = existing[0]!.id;
    created = false;
    // Use the STORED email, never a fresh hostname-derived one. A rehomed
    // machine changes `hostname()` but the user row is immutable; passing the
    // recomputed email into personal-org provisioning makes
    // provisionMemberAndCoreIdentities refuse ("user does not own the member
    // email") on every boot forever. The stored value is the address the
    // account was born with.
    userEmail = existing[0]!.email.trim().toLowerCase();
  } else {
    userId = `user_install_${generateSecureToken(8)}`;
    userEmail = installOperatorEmail();
    const hashed = await hashPassword(encryptionKey);

    await sql.begin(async (tx) => {
      await tx`
        INSERT INTO "user"
          (id, name, email, "emailVerified", principal_kind, "createdAt", "updatedAt")
        VALUES
          (${userId}, ${'Local Install'}, ${userEmail}, true,
           ${INSTALL_OPERATOR_KIND}, NOW(), NOW())
      `;

      // Better Auth's email-password adapter expects one `account` row
      // per user with providerId='credential' and the hashed password
      // stored in the `password` column. accountId matches userId by
      // convention.
      const accountId = `acct_install_${generateSecureToken(8)}`;
      await tx`
        INSERT INTO "account"
          (id, "accountId", "providerId", "userId", password,
           "createdAt", "updatedAt")
        VALUES
          (${accountId}, ${userId}, 'credential', ${userId}, ${hashed},
           NOW(), NOW())
      `;
    });
    created = true;
  }

  // Personal org provisioning is convergent: ensurePersonalOrganization
  // is itself idempotent (returns the existing org if one is already
  // tagged with this user.id in metadata). Running it on every boot
  // closes the gap where a transient failure on first boot used to
  // leave the operator without a personal org forever.
  try {
    await ensurePersonalOrganization({
      id: userId,
      email: userEmail,
      name: 'Local Install',
      username: null,
    });
  } catch (err) {
    console.error(
      '[install-operator] Personal-org provisioning failed; will retry on next boot:',
      err
    );
  }

  return { userId, created };
}

item.stdout:
    installedProviderRoutes?: Record<string, string>;
  }
): {
  provider: string;
  /** Lobu provider slug retained for exact settings/CTA targeting. */
  providerSlug: string;
  modelId: string;
} {
  const defaultModelRef = overrides?.defaultModel || "";
  const defaultProvider = overrides?.defaultProvider || "";
  // The provider's LOBU id (e.g. "claude"), present only when it differs from
  // `defaultProvider` (the upstream slug, e.g. "anthropic"). Lobu stores models
  // prefixed with the Lobu id, so it must be stripped too — otherwise a
  // "claude/…" model reaches the upstream API verbatim and 404s.
  const defaultProviderSlug = overrides?.defaultProviderSlug || "";

  const normalizedRaw = rawModelRef?.trim();
  const modelRef = normalizedRaw || defaultModelRef;

  // A model must be explicitly configured — Lobu no longer silently picks a
  // provider default, because "newest available" is unreliable (e.g. the
  // Anthropic API lists preview models an account can't actually use). Surface
  // an actionable error so the operator selects a concrete model.
  if (!modelRef) {
    throw new Error(
      "No model resolved for this run. Set the agent's default model, a " +
        "per-behavior model, or an org default inference provider."
    );
  }

  // An explicit "<provider>/<model>" ref selects its own provider — a Behavior
  // pinned to a provider the base agent does not use, or simply an agent pinned
  // to a provider the deployment does not publish as its default. `defaultProvider`
  // is a deployment-level fact and the ref is a run-level one, so the ref wins;
  // its Lobu ID is routed to the upstream runtime slug (claude → anthropic).
  //
  // The installed-route guard is what keeps this fail-safe. It preserves model
  // namespaces such as OpenRouter's "anthropic/claude-sonnet-4", where
  // "anthropic" is not a separately installed provider and the configured
  // OpenRouter route must win, and it stops an uninstalled prefix from
  // conjuring a provider the org never configured. Lobu stores refs as
  // "<lobu-slug>/<model>", so OpenRouter's own entry keeps its prefix
  // ("openrouter/openai/gpt-4o") and never collides with an installed OpenAI.
  //
  // Derived from the RESOLVED `modelRef`, not `normalizedRaw`. A pin is a pin
  // whichever field carries it: most runs have no per-turn model, so the agent's
  // configured `models[0]` arrives as `defaultModel` and `normalizedRaw` is
  // empty. Reading the raw argument here skipped the guard for exactly those
  // runs, and they silently executed on the gateway's fallback-scanned
  // `defaultProvider` with the foreign ref passed through as the model id
  // (observed live: "openai/gpt-5.6-luna" sent to qwen). `defaultProvider` is a
  // fallback-scan result; a configured pin to an INSTALLED provider outranks it.
  const explicitParts = modelRef.split("/").filter(Boolean);
  const explicitProvider = explicitParts[0];
  if (
    explicitParts.length >= 2 &&
    explicitProvider &&
    overrides?.installedProviderRoutes?.[explicitProvider] &&
    explicitProvider !== defaultProvider &&
    explicitProvider !== defaultProviderSlug
  ) {
    const routedProvider = overrides.installedProviderRoutes[explicitProvider];
    let modelId = explicitParts.slice(1).join("/");
    if (modelId === "auto") {
      modelId =
        DEFAULT_PROVIDER_MODELS[explicitProvider] ??
        DEFAULT_PROVIDER_MODELS[routedProvider] ??
        modelId;
    }
    return {
      provider: routedProvider,
      providerSlug: explicitProvider,
      modelId,
    };
  }

  // When the agent has an explicitly configured provider, route to it and pass
  // the model string AS-IS. The model is expressed in that provider's own
  // namespace — e.g. OpenRouter slugs like "anthropic/claude-sonnet-4" or
  // "openai/gpt-4o" mean "OpenRouter's anthropic/openai model", not "switch to
  // the anthropic/openai provider". Splitting on "/" here would mis-route them.
  if (defaultProvider) {
    let modelId = modelRef;
    // Resolve "auto" to the configured provider's default model FIRST — the
    // default itself may carry a redundant prefix (e.g. nvidia →
    // "nvidia/moonshotai/kimi-k2.5"), so stripping has to run after this.
    if (modelId === "auto") {
      const fallback = DEFAULT_PROVIDER_MODELS[defaultProvider];
      if (fallback) {
        logger.info(`Resolved auto model for ${defaultProvider}: ${fallback}`);
        modelId = fallback;
      }
    }
    // Then strip a redundant leading "<configured-provider>/" self-prefix. Lobu
    // names models "provider/model" ("nvidia/…"), but the upstream
    // provider's own namespace is the bare code — shipping the Lobu
    // prefix makes sdkCompat:openai providers 400 "Unknown
    // Model". Only the configured provider's OWN id is stripped, so a foreign
    // namespace slug (OpenRouter's "anthropic/claude-sonnet-4") stays intact.
    // Runs after the auto-resolution above so a prefixed default is covered too.
    //
    // `defaultProvider` is the UPSTREAM slug ("anthropic"); strip that AND the
    // LOBU slug ("claude") when they differ, since the stored model is prefixed
    // with the Lobu id. Without the second strip, "claude/claude-opus-4-8"
    // reaches the Anthropic API verbatim and 404s.
    if (modelId.startsWith(`${defaultProvider}/`)) {
      modelId = modelId.slice(defaultProvider.length + 1);
    } else if (
      defaultProviderSlug &&
      defaultProviderSlug !== defaultProvider &&
      modelId.startsWith(`${defaultProviderSlug}/`)
    ) {
      modelId = modelId.slice(defaultProviderSlug.length + 1);
    }
    // Reaching here means the ref did NOT name an installed provider other than
    // the configured one — it is the configured provider's own model, a bare
    // model id, or a prefix no installed provider answers to (an aggregator's
    // internal namespace like "anthropic/claude-sonnet-4" with no Anthropic
    // installed, or simply a provider this deployment lacks). None of those
    // names a better route or a reachable CTA target than the configured
    // provider, so routing and attribution both stay on it.
    return {
      provider: defaultProvider,
      providerSlug: defaultProviderSlug || defaultProvider,
      modelId,
    };
  }

  // Auto / no-configured-provider mode: derive the provider from the model
  // string's first segment ("provider/model").
  const parts = modelRef.split("/").filter(Boolean);
    // not a Lobu prefix — it must pass through unchanged.
    const result = resolveModelRef("anthropic/claude-sonnet-4", {
      defaultProvider: "openrouter",
      defaultProviderSlug: "openrouter",
    });
    expect(result.provider).toBe("openrouter");
    expect(result.modelId).toBe("anthropic/claude-sonnet-4");
  });

  test("an explicit ref switches to another installed provider", () => {
    const result = resolveModelRef("groq/llama-3.3-70b-versatile", {
      defaultModel: "claude/claude-sonnet-4-5",
      defaultProvider: "anthropic",
      defaultProviderSlug: "claude",
      installedProviderRoutes: { claude: "anthropic", groq: "groq" },
    });

    expect(result.provider).toBe("groq");
    expect(result.providerSlug).toBe("groq");
    expect(result.modelId).toBe("llama-3.3-70b-versatile");
  });

  test("an explicit ref resolves auto against the selected installed provider", () => {
    const result = resolveModelRef("nvidia/auto", {
      defaultModel: "claude/claude-sonnet-4-5",
      defaultProvider: "anthropic",
      defaultProviderSlug: "claude",
      installedProviderRoutes: { claude: "anthropic", nvidia: "nvidia" },
    });

    expect(result.provider).toBe("nvidia");
    expect(result.modelId).toBe(DEFAULT_PROVIDER_MODELS.nvidia);
  });

  test("an explicit ref routes a Lobu provider ID to its upstream runtime slug", () => {
    const result = resolveModelRef("claude/claude-sonnet-4-5", {
