    release: process.env.SENTRY_RELEASE || process.env.APP_GIT_SHA || undefined,
    // 0.1 produced ~250k spans/day (~7.5M/mo) and exhausted the plan's 5M span
    // quota by day ~20 of the usage period. 0.02 keeps ~50k/day (~1.5M/mo) —
