      SELECT e.occurred_at, e.created_at
      FROM events e
      WHERE e.semantic_type = 'canvas_state'
        AND (e.metadata->>'watcher_id')::bigint = ${Number(seeded.watcherId)}
        AND e.supersedes_event_id IS NOT NULL
    `;
