import { beforeAll, beforeEach, describe, expect, it } from 'vitest';
import { manageBehaviors } from '../../../tools/admin/manage_behaviors';
import type { ToolContext } from '../../../tools/registry';
import { insertEvent } from '../../../utils/insert-event';
