  }

  if (!alreadyRegistered) {
    DEFAULT_PROVIDER_BASE_URL_ENV[id] = config.baseUrlEnvVar;
  }

  // Always update default model and alias even for pre-registered providers
  if (config.defaultModel && !DEFAULT_PROVIDER_MODELS[id]) {
