  return {
    version: packageJson.version,
    revision:
      cleanString(env?.APP_GIT_SHA) ||
      cleanString(process.env.APP_GIT_SHA) ||
      'unknown',
    build_time:
      cleanString(env?.APP_BUILD_TIME) ||
