				sources: [{ name: "content", query: "@feed:nonexistent-typo" }],
			})
		).rejects.toThrow(/nonexistent-typo/i);
	});

	it("accepts an @feed ref that points at a streaming (channel) feed", async () => {
		// A streaming/channel feed compiles to a membership-gated read over
		// channel_messages (compileChannelMessagesVisibility), so it IS a valid
		// @feed source — the gate keeps enforced-channel content from leaking.
		const sql = getTestDb();
		const connection = await createTestConnection({
			organization_id: ownerOrgId,
			connector_key: "slack",
			display_name: "Streaming Feed Connection",
			slug: "streaming-feed-connection",
		});
		await sql`
			INSERT INTO feeds (organization_id, connection_id, feed_key, display_name, status, kind, virtual, config)
			VALUES (${ownerOrgId}, ${connection.id}, 'slack:C123', 'general', 'active', 'streaming', false, ${sql.json({ store: "channel_messages" })}::jsonb)
		`;

		const created = (await owner.behaviors.create({
			entity_id: inOrgEntityId,
			slug: "streaming-feed-src",
			name: "Streaming Feed Src",
			prompt: "Track stuff.",
			agent_id: agentId,
			sources: [{ name: "content", query: "@feed:slack:C123" }],
		})) as { behavior_id: string };
		expect(created.behavior_id).toBeTruthy();
	});

	it("rejects create when an @entity ref is not a type in the org", async () => {
		await expect(
			owner.behaviors.create({
				entity_id: inOrgEntityId,
				slug: "typo-entity",
				name: "Typo Entity",
				prompt: "Track stuff.",
				agent_id: agentId,
				sources: [{ name: "ctx", query: "@entity:nope-not-a-type" }],
			})
		).rejects.toThrow(/entity type/i);
	});

	it("rejects create when an @metric ref points at an undeclared measure", async () => {
		await expect(
			owner.behaviors.create({
				entity_id: inOrgEntityId,
				slug: "typo-metric",
				name: "Typo Metric",
				prompt: "Track stuff.",
				agent_id: agentId,
				sources: [
					{
						name: "m",
						query: "@metric:company.totally-fake-measure",
					},
				],
			})
		).rejects.toThrow(/measure/i);
	});

	// ---- BUG B ----

	it("create_from_version rejects a cross-org entity_id", async () => {
		const base = (await owner.behaviors.create({
			entity_id: inOrgEntityId,
			slug: "cfv-base",
			name: "CFV Base",
			prompt: "Track stuff.",
			agent_id: agentId,
			sources: [{ name: "content", query: "SELECT id FROM events" }],
		})) as { behavior_id: string };

		const sql = getTestDb();
		const [row] = await sql<{ current_version_id: number }[]>`
      SELECT current_version_id FROM watchers WHERE id = ${base.behavior_id}
    `;
		const versionId = Number(row?.current_version_id);
		expect(versionId).toBeGreaterThan(0);

		await expect(
			owner.behaviors.createFromVersion({
				version_id: versionId,
				entity_ids: [foreignEntityId],
			})
		).rejects.toThrow(new RegExp(String(foreignEntityId)));

		// No watcher leaked pointing at the foreign entity.
		const leaked = await sql<{ id: number }[]>`
      SELECT id FROM watchers
      WHERE organization_id = ${ownerOrgId} AND ${foreignEntityId} = ANY(entity_ids)
    `;
		expect(leaked.length).toBe(0);
	});

	it("create_from_version accepts an in-org entity_id", async () => {
		const base = (await owner.behaviors.create({
			entity_id: inOrgEntityId,
			slug: "cfv-base-ok",
			name: "CFV Base OK",
			prompt: "Track stuff.",
			agent_id: agentId,
			sources: [{ name: "content", query: "SELECT id FROM events" }],
		})) as { behavior_id: string };

		const sql = getTestDb();
		const [row] = await sql<{ current_version_id: number }[]>`
      SELECT current_version_id FROM watchers WHERE id = ${base.behavior_id}
    `;
		const versionId = Number(row?.current_version_id);

		const result = (await owner.behaviors.createFromVersion({
			version_id: versionId,
			entity_ids: [inOrgEntityId],
		})) as { created: Array<{ behavior_id: string }> };
		expect(result.created.length).toBe(1);
	});

	// ---- BUG C: delete/update must not archive/mutate cross-org rows ----
	// requireWatcherAccess lets an id that is absent from the caller's org fall
	// through to the per-id aggregate (so genuinely-missing ids report "not
	// found"). Watcher ids are sequential integers, so a foreign-tenant row can
	// occupy the id the caller aimed at. The mutation SQL is org-scoped so that
	// foreign row is never archived — it only reports as a per-id failure.
	it("delete cannot archive a watcher owned by another org", async () => {
		const foreignOrg = await createTestOrganization({ name: "Delete Foreign Org" });
		const foreignUser = await createTestUser({ email: "delete-foreign@test.com" });
		await addUserToOrganization(foreignUser.id, foreignOrg.id, "owner");
		const foreignClient = await TestApiClient.for({
			organizationId: foreignOrg.id,
			userId: foreignUser.id,
			memberRole: "owner",
		});
		const foreignAgent = await createTestAgent({
			organizationId: foreignOrg.id,
			ownerUserId: foreignUser.id,
		});
		const foreignWatcher = (await foreignClient.behaviors.create({
			slug: "foreign-del-target",
			name: "Foreign Behavior",
			prompt: "Track stuff.",
			agent_id: foreignAgent.agentId,
			sources: [{ name: "content", query: "SELECT id FROM events" }],
		})) as { behavior_id: string };
		const foreignId = String(foreignWatcher.behavior_id);

		// The owner (a different org) targets the foreign row's id directly. It
		// exists under another tenant, so requireWatcherAccess rejects it 403 —
		// and even if that gate were bypassed, the org-scoped archive UPDATE
		// leaves the foreign row untouched.
		await expect(
			owner.behaviors.delete({ behavior_ids: [foreignId] })
		).rejects.toMatchObject({ httpStatus: 403 });

		// The foreign row is untouched — still active, not archived.
		const sql = getTestDb();
		const [after] = await sql<{ status: string }[]>`
      SELECT status FROM watchers WHERE id = ${foreignId}
    `;
		expect(after?.status).toBe("active");
	});
});

