Makefile-28-	@echo "  make bump SUBMODULE=<path> [TARGET=<ref>]  - Lightweight worktree + commit + PR for a trivial submodule pointer bump (skips bun install, .env, ports)"
Makefile-29-	@echo "  make review [BASE=<branch>]                - Run the cross-harness LLM reviewer against the local diff (deterministic suites run in CI); posts pi-review status and PR comment"
Makefile-30-	@echo "  make review-fix [BASE=<branch>]            - Pre-review fixer: reviewer CLI with write access fixes review-grade findings in the tree; posts nothing"
Makefile:31:	@echo "  make ui-review [ARTIFACT=<https-url>]       - Publish exact-SHA visual proof for an Owletto pointer on its merged PR; OPEN=1 opens that PR"
