Makefile-33-	@echo "  make pre-pr-remote [REMOTE_JOBS='unit …']  - Run staged full Linux CI on Depot (default final gate; no local CPU)"
Makefile-34-	@echo "  make pre-pr                                - Run the CPU-heavy deterministic gate locally (explicit fallback)"
