import packageJson from '../../package.json';

interface RuntimeEnvLike {
  ENVIRONMENT?: string;
  NODE_ENV?: string;
  APP_GIT_SHA?: string;
  APP_BUILD_TIME?: string;
}

function cleanString(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : undefined;
}

export function resolveRuntimeEnvironment(env?: RuntimeEnvLike | null): string {
  return (
    cleanString(env?.ENVIRONMENT) ||
    cleanString(env?.NODE_ENV) ||
    cleanString(process.env.ENVIRONMENT) ||
    cleanString(process.env.NODE_ENV) ||
    'development'
  );
}

export function resolveSentryRuntime(env?: RuntimeEnvLike | null): {
  environment: string;
  isDevelopment: boolean;
  devTaggedAsProduction: boolean;
} {
  // Sentry's environment tag comes from ENVIRONMENT alone — never NODE_ENV.
  // The Docker images bake in NODE_ENV=production (docker/app, docker/worker),
  // so a NODE_ENV fallback would tag every compose/local stack that omits
  // ENVIRONMENT as "production" and pollute the prod Sentry stream.
  const declaredEnvironment =
    cleanString(env?.ENVIRONMENT) ||
    cleanString(process.env.ENVIRONMENT) ||
    'development';
  const nodeEnvironment =
    cleanString(env?.NODE_ENV) || cleanString(process.env.NODE_ENV);
  const devTaggedAsProduction =
    nodeEnvironment === 'development' && declaredEnvironment === 'production';
  const environment = devTaggedAsProduction
    ? 'development'
    : declaredEnvironment;

  return {
    environment,
    isDevelopment:
      nodeEnvironment === 'development' || environment === 'development',
    devTaggedAsProduction,
  };
}

export function getRuntimeInfo(env?: RuntimeEnvLike | null) {
  return {
    version: packageJson.version,
    revision:
      cleanString(env?.APP_GIT_SHA) ||
      cleanString(process.env.APP_GIT_SHA) ||
      'unknown',
    build_time:
      cleanString(env?.APP_BUILD_TIME) ||
      cleanString(process.env.APP_BUILD_TIME) ||
      null,
    environment: resolveRuntimeEnvironment(env),
  };
}
import { describe, expect, it } from 'vitest';
import {
  getRuntimeInfo,
  resolveRuntimeEnvironment,
  resolveSentryRuntime,
} from '../runtime-info';

describe('resolveRuntimeEnvironment', () => {
  it('prefers ENVIRONMENT over NODE_ENV', () => {
    expect(resolveRuntimeEnvironment({ ENVIRONMENT: 'production', NODE_ENV: 'development' })).toBe(
      'production'
    );
  });

  it('falls back to NODE_ENV when ENVIRONMENT is missing', () => {
    expect(resolveRuntimeEnvironment({ NODE_ENV: 'production' })).toBe('production');
  });
});

describe('resolveSentryRuntime', () => {
  it('ignores the baked-in NODE_ENV=production when ENVIRONMENT is missing', () => {
    // Docker images always set NODE_ENV=production; only an explicit
    // ENVIRONMENT may tag Sentry events as production.
    expect(resolveSentryRuntime({ NODE_ENV: 'production' })).toEqual({
      environment: 'development',
      isDevelopment: true,
      devTaggedAsProduction: false,
    });
  });

  it('tags production only when ENVIRONMENT declares it', () => {
    expect(
      resolveSentryRuntime({ ENVIRONMENT: 'production', NODE_ENV: 'production' })
    ).toEqual({
      environment: 'production',
      isDevelopment: false,
      devTaggedAsProduction: false,
    });
  });

  it('downgrades only a development runtime carrying a production tag', () => {
    expect(
      resolveSentryRuntime({ ENVIRONMENT: 'production', NODE_ENV: 'development' })
    ).toEqual({
      environment: 'development',
      isDevelopment: true,
      devTaggedAsProduction: true,
    });
  });
});

describe('getRuntimeInfo', () => {
  it('returns revision and build metadata from env', () => {
    expect(
      getRuntimeInfo({
        NODE_ENV: 'production',
        APP_GIT_SHA: 'abc123',
        APP_BUILD_TIME: '2026-04-12T23:00:00Z',
      })
    ).toMatchObject({
      environment: 'production',
      revision: 'abc123',
      build_time: '2026-04-12T23:00:00Z',
    });
  });
});

