diff --git a/packages/agent-worker/src/runtime/model-resolver.ts b/packages/agent-worker/src/runtime/model-resolver.ts
index 216424a03..b4969f176 100644
--- a/packages/agent-worker/src/runtime/model-resolver.ts
+++ b/packages/agent-worker/src/runtime/model-resolver.ts
@@ -344,24 +344,33 @@ export function resolveModelRef(
   // "openai/gpt-4o" mean "OpenRouter's anthropic/openai model", not "switch to
   // the anthropic/openai provider". Splitting on "/" here would mis-route them.
   if (defaultProvider) {
+    // Normalize the configured provider's own prefix before checking the
+    // sentinel. Otherwise "nvidia/auto" reaches the upstream API as the
+    // literal model "auto".
+    const normalizedModelId = stripOwnProviderPrefix(
+      modelRef,
+      defaultProvider,
+      defaultProviderSlug
+    );
     let modelId = modelRef;
-    // Resolve "auto" to the configured provider's default model FIRST — the
-    // default itself may carry a redundant prefix (e.g. nvidia →
-    // "nvidia/moonshotai/kimi-k2.5"), so stripping has to run after this.
-    if (modelId === "auto") {
+    if (normalizedModelId === "auto") {
       const fallback = DEFAULT_PROVIDER_MODELS[defaultProvider];
       if (fallback) {
         logger.info(`Resolved auto model for ${defaultProvider}: ${fallback}`);
         modelId = fallback;
+      } else {
+        modelId = normalizedModelId;
       }
     }
