     // names models "provider/model" ("nvidia/…"), but the upstream
     // provider's own namespace is the bare code — shipping the Lobu
     // prefix makes sdkCompat:openai providers 400 "Unknown
     // Model". Only the configured provider's OWN id is stripped, so a foreign
     // namespace slug (OpenRouter's "anthropic/claude-sonnet-4") stays intact.
-    // Runs after the auto-resolution above so a prefixed default is covered too.
+    // This second pass ensures a prefixed default is covered too.
     //
     // `defaultProvider` is the UPSTREAM slug ("anthropic"); strip that AND the
     // LOBU slug ("claude") when they differ, since the stored model is prefixed
diff --git a/packages/server/src/utils/__tests__/runtime-info.test.ts b/packages/server/src/utils/__tests__/runtime-info.test.ts
index ae018240e..1dffc16f8 100644
--- a/packages/server/src/utils/__tests__/runtime-info.test.ts
+++ b/packages/server/src/utils/__tests__/runtime-info.test.ts
@@ -20,12 +20,23 @@ describe('resolveRuntimeEnvironment', () => {
 describe('resolveSentryRuntime', () => {
   it('ignores the baked-in NODE_ENV=production when ENVIRONMENT is missing', () => {
     // Docker images always set NODE_ENV=production; only an explicit
-    // ENVIRONMENT may tag Sentry events as production.
-    expect(resolveSentryRuntime({ NODE_ENV: 'production' })).toEqual({
-      environment: 'development',
