in `blockers`.\012\012\012Review the diff. Emit only the JSON verdict. --model fable --effort high --json-schema {\012  "type": "object",\012  "description": "Lobu merge-review verdict. Judge the diff against the requested base and report concrete changed-path defects only.",\012  "additionalProperties": false,\012  "required": [\012    "bug_free_confidence",\012    "bugs",\012    "slop",\012    "simplicity",\012    "blockers",\012    "change_type",\012    "behavior_change_risk",\012    "tests_adequate",\012    "suggested_fixes",\012    "notes",\012    "categories"\012  ],\012  "properties": {\012    "bug_free_confidence": {\012      "type": "integer",\012      "minimum": 0,\012      "maximum": 100,\012      "description": "Confidence that the diff is bug-free; 90 or more requires strong verification."\012    },\012    "bugs": {\012      "type": "integer",\012      "minimum": 0,\012      "description": "Count of concrete defects caused by the diff."\012    },\012    "slop": {\012      "type": "integer",\012      "minimum": 0,\012      "maximum": 100,\012      "description": "Amount of unnecessary or generated waste; lower is better."\012    },\012    "simplicity": {\012      "type": "integer",\012      "minimum": 0,\012      "maximum": 100,\012      "description": "How simple and maintainable the change is; higher is better."\012    },\012    "blockers": {\012      "type": "array",\012      "description": "Merge-blocking defects caused by the diff.",\012      "items": { "type": "string" }\012    },\012    "change_type": {\012      "type": "string",\012      "enum": ["feat", "fix", "refactor", "docs", "chore", "test", "deps"]\012    },\012    "behavior_change_risk": {\012      "type": "string",\012      "enum": ["none", "low", "medium", "high"]\012    },\012    "tests_adequate": {\012      "type": "boolean",\012      "description": "Whether changed behavior has adequate automated coverage."\012    },\012    "suggested_fixes": {\012      "type": "array",\012      "items": {\012        "type": "object",\012        "additionalProperties": false,\012        "required": ["file", "line", "change"],\012        "properties": {\012          "file": { "type": "string" },\012          "line": { "type": ["integer", "null"], "minimum": 1 },\012          "change": { "type": "string" }\012        }\012      }\012    },\012    "notes": {\012      "type": "string",\012      "description": "Concise review summary, including any non-blocking or environmental observations."\012    },\012    "categories": {\012      "type": "object",\012      "additionalProperties": false,\012      "required": [\012        "src",\012        "tests",\012        "docs",\012        "config",\012        "deps",\012        "migrations",\012        "ci",\012        "generated"\012      ],\012      "properties": {\012        "src": { "type": "integer", "minimum": 0 },\012        "tests": { "type": "integer", "minimum": 0 },\012        "docs": { "type": "integer", "minimum": 0 },\012        "config": { "type": "integer", "minimum": 0 },\012        "deps": { "type": "integer", "minimum": 0 },\012        "migrations": { "type": "integer", "minimum": 0 },\012        "ci": { "type": "integer", "minimum": 0 },\012        "generated": { "type": "integer", "minimum": 0 }\012      }\012    }\012  }\012} --output-format text --no-session-persistence --tools Bash,Read,Grep,LS --permission-mode bypassPermissions

